head.script:
scwin.gLdMktTp = js_market;
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
        $c.cm.PanelToGroupBox(panel_2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30011.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    await scwin.search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30011.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30011.btn_Search_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&MKT_ID=" + scwin.gLdMktTp;
    url += "&SUBMIT_SYS_USE_YN=" + cmb_SUBMIT_SYS_USE_YN.getValue();
    url += "&SMS_TRNSM_YN=" + cmb_SMS_TRNSM_YN.getValue();
    url += "&SCREN_ID=" + 'ULDSTF30011.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name ShowNoData
 * @description 팝업에서 보여지는 이미지가 틀려 여기에서 하드코딩으로 넣는다.
 * @param {*} sval sval
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ShowNoData = async function(sval) {
    let tem1 = sval.style.getStyle("width");
    let temLeft = sval.style.left;
    let temTop = sval.style.top;
    let tem2 = sval.style.getStyle("height");
    tem1 = tem1.substring(0, (tem1.length - 2));
    temLeft = temLeft.substring(0, (temLeft.length - 2));
    tem2 = tem2.substring(0, (tem2.length - 2));
    temTop = temTop.substring(0, (temTop.length - 2));
    vXpos = ((tem1 / 2) - 100) + Number(temLeft);
    vYpos = ((tem2 / 2) - 18) + Number(temTop);
    if ($c.frame.path("NoData") === null) {
        await $c.frame.CreateFrame("NoData", "/common/noData.gfm", "페이지 로딩중...", 143, 148, 200, 35, "sunken", 0, 0, true);
    }
};

/**
 * @method
 * @name CloseWin
 * @description 팝업에서 보여지는 이미지가 틀려 여기에서 하드코딩으로 넣는다.
 * @param {Number} cnt cnt
 * @param {*} sval sval
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.CloseWin = async function(cnt, sval) {
    if ($c.frame.path("LoadingImg") !== null) {
        await $c.win.closePopup();
        if (cnt === 0) $c.cm.ShowNoData(sval);
    }
};
